import { useUser } from "./hooks/useUser"

export default function UsersPage() {
    const users = useUser()
    const userWithId1 = useUser(1)
   return (
    <div>
        <h1>Users Page</h1>
        <div className="flex p-5 bg-blue-300">
            <p>User with id 1 - </p>
            <p>{userWithId1.data.name}</p>
        </div>
        <div>
            {users.isLoading && <p>Users is loading...</p>}    
            {users.isError && <p>{users.isError}</p>}
            {<div className="p-5 mt-5 bg-blue-300">
                {users.data.map((user) => (
                    <p className="my-2">{user.id}</p>
                ))}
            </div>}
        </div> 
    </div>
   )
}
